using Swashbuckle.AspNetCore.Annotations;namespace GraphApi.Models.NTF.Notificaciones{    [SwaggerSchema("Modelo de lectura de un Notificacione")]    [GraphQLDescription("Objeto que representa un Notificacione existente.")]    public class clReadNotificaciones    {        [SwaggerSchema("Identificador único del Notificacione")]        [GraphQLDescription("Identificador único del Notificacione")]        public int? NotificacionID { get; set; }        [SwaggerSchema("UsuarioID")]        [GraphQLDescription("UsuarioID")]        public int? UsuarioID { get; set; }        [SwaggerSchema("Titulo")]        [GraphQLDescription("Titulo")]        public string? Titulo { get; set; } = default!;        [SwaggerSchema("Mensaje")]        [GraphQLDescription("Mensaje")]        public string? Mensaje { get; set; } = default!;        [SwaggerSchema("Leido")]        [GraphQLDescription("Leido")]        public bool? Leido { get; set; }        [SwaggerSchema("FechaCreacionNotificacion")]        [GraphQLDescription("FechaCreacionNotificacion")]        public DateTime? FechaCreacionNotificacion { get; set; }        [SwaggerSchema("TipoNotificacionID")]        [GraphQLDescription("TipoNotificacionID")]        public int? TipoNotificacionID { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }    [SwaggerSchema("Modelo de creación de un Notificacione")]    [GraphQLDescription("Input para crear un Notificacione.")]    public class clCreateNotificaciones    {        [GraphQLNonNullType] [SwaggerSchema("UsuarioID")]        [GraphQLDescription("UsuarioID")]        public int UsuarioID { get; set; }        [GraphQLNonNullType] [SwaggerSchema("Titulo")]        [GraphQLDescription("Titulo")]        public string Titulo { get; set; } = default!;        [GraphQLNonNullType] [SwaggerSchema("Mensaje")]        [GraphQLDescription("Mensaje")]        public string Mensaje { get; set; } = default!;        [GraphQLNonNullType] [SwaggerSchema("Leido")]        [GraphQLDescription("Leido")]        public bool Leido { get; set; }        [GraphQLNonNullType] [SwaggerSchema("FechaCreacionNotificacion")]        [GraphQLDescription("FechaCreacionNotificacion")]        public DateTime FechaCreacionNotificacion { get; set; }        [SwaggerSchema("TipoNotificacionID")]        [GraphQLDescription("TipoNotificacionID")]        public int? TipoNotificacionID { get; set; }        [GraphQLNonNullType] [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool bEliminado { get; set; }    }    [SwaggerSchema("Modelo de actualización de un Notificacione")]    [GraphQLDescription("Input para actualizar parcialmente un Notificacione.")]    public class clUpdateNotificaciones    {        [SwaggerSchema("Identificador único del Notificacione")]        [GraphQLDescription("Identificador único del Notificacione")]        public int? NotificacionID { get; set; }        [SwaggerSchema("UsuarioID")]        [GraphQLDescription("UsuarioID")]        public int? UsuarioID { get; set; }        [SwaggerSchema("Titulo")]        [GraphQLDescription("Titulo")]        public string? Titulo { get; set; }        [SwaggerSchema("Mensaje")]        [GraphQLDescription("Mensaje")]        public string? Mensaje { get; set; }        [SwaggerSchema("Leido")]        [GraphQLDescription("Leido")]        public bool? Leido { get; set; }        [SwaggerSchema("FechaCreacionNotificacion")]        [GraphQLDescription("FechaCreacionNotificacion")]        public DateTime? FechaCreacionNotificacion { get; set; }        [SwaggerSchema("TipoNotificacionID")]        [GraphQLDescription("TipoNotificacionID")]        public int? TipoNotificacionID { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }}